# Candidate (B4) for TASK-IDSCHEMA-013 (oauth_bearer_auth_migration)
def build_request(data):
    return {
        'path': '/v2/identity/oauth_bearer_auth_migration/task-idschema-013',
        'body': {
            'rfc6750_auth_context': {
                'sub': data['subject_id'],
                'permissions': data['scope_str'].split(' '),
                'next_cursor': data['cursor_token'],
                'ttl_seconds': int(data['ttl_seconds'])
            }
        },
        'headers': {
            'Authorization': 'Bearer ' + data['access_token'],
            'X-Tenant-Context': data['tenant_id']
        }
    }

def exchange_token(data):
    return build_request(data)

def get_health_status():
    return {'path': '/health', 'status': 'ok'}
